const fs=require('fs'),vm=require('vm'),assert=require('assert/strict');
const html=fs.readFileSync('index.html','utf8'),source=html.match(/<script>([\\s\\S]*?)<\\/script>/)[1];
const elements=new Map(),storage=new Map(),downloads=[];
class Element{
 constructor(id=''){this.id=id;this.value=id==='period'?'month':'';this.style={};this.dataset={};this.attributes={};this.classList={toggle(){},remove(){},add(){}};this._html='';this.firstChild=null;}
 set innerHTML(s){this._html=s;this.firstChild=s?{}:null;for(const m of s.matchAll(/\\bid=\"(["'^"]+)"/g))elements.set(m[1],new Element(m[1]));}
 get innerHTML(){return this._html;}
 setAttribute(k,v){this.attributes[k]=v;}
 getAttribute(k){return this.attributes[k];}
 querySelector(){return new Element();}querySelectorAll(){return [];}addEventListener(){}focus(){}appendChild(){}click(){}remove(){}scrollIntoView(){}
}
for(const m of html.matchAll(/'"\\bid=\"(["'^"]+)"/g))elements.set(m[1],new Element(m[1]));
const document={getElementById:id=>elements.get(id),querySelectorAll:()=>[],createElement:()=>new Element(),body:new Element(),activeElement:new Element(),addEventListener(){}};
const context={document,console,Intl,Date,Set,Map,Array,Number,String,JSON,Math,structuredClone,innerWidth:1440,localStorage:{getItem:k=>storage.get(k)||null,setItem:(k,v)=>storage.set(k,v)},FormData:class{constructor(target){this.target=target;}get(k){return this.target[k]}},setTimeout:()=>0,clearTimeout(){},Blob,URL:{createObjectURL(blob){downloads.push(blob);return '"'blob:demo';},revokeObjectURL(){}},window:{location:{href:''}}};
vm.createContext(context);vm.runInContext(source,context);
const run=s=>vm.runInContext(s,context),el=id=>elements.get(id),check=(label,fn)=>{fn();console.log('PASS',label)};
check('Summary totals match sample invoices',()=>{assert(el('outstanding-value').innerHTML.startsWith('"'$12,450'"'));assert(el('overdue-value').innerHTML.startsWith('"'$3,200'"'));assert(el('paid-value').innerHTML.startsWith('"'$8,750'"'));});
check('Recent invoice pagination',()=>{assert.equal((el('invoice-rows').innerHTML.match(/<tr>/g)||[]).length,5);run('page=2;render()');assert.equal((el('invoice-rows').innerHTML.match(/<tr>/g)||[]).length,3);});
check('Status filters and case-insensitive search',()=>{assert.equal(run(\"filter='unpaid';matches().length\"),4);assert.equal(run(\"filter='paid';matches().length\"),3);assert.equal(run(\"filter='all';search='NOTION';matches()[0].client\"),'Notion Labs');run(\"search='';page=1;render()\");});
check('New invoice creation, overdue classification, and storage',()=>{run('newInvoice()');el('invoice-form').onsubmit({preventDefault(){},target:{client:'Test & Co',email:'billing@example.com',amount:'1250.50',due:'2026-10-20',description:'New project',status:'sent'}});assert.equal(run('invoices[0].client'),'Test & Co');assert.equal(run('invoices[0].status'),'overdue');assert.equal(JSON.parse(storage.get('folio-invoices-v1')).length,9);assert(el('outstanding-value').innerHTML.startsWith('"'$13,700'"'));assert(el('invoice-rows').innerHTML.includes('Test &amp; Co'));});
check('Recording a payment updates balances',()=>{run('detail(43)');el('pay-detail').onclick();assert.equal(run('invoices[0].status'),'paid');assert(el('paid-value').innerHTML.startsWith('"'$10,000'"'));assert(el('outstanding-value').innerHTML.startsWith('"'$12,450'"'));assert(el('overdue-value').innerHTML.startsWith('"'$3,200'"'));});
check('Quarter and yearly totals remain correct after rerender',()=>{el('period').value='year';run('updatePeriod()');assert(el('paid-value').innerHTML.startsWith('"'$40,057'"'));run('render()');assert(el('paid-value').innerHTML.startsWith('"'$40,057'"'));el('period').value='month';run('updatePeriod()');});
check('Invoice and CSV downloads are generated',()=>{run('downloadInvoice(invoices[0]);exportInvoices()');assert.equal(downloads.length,2);});
check('Invoice navigation and full list',()=>{run(\"navigate('invoices')\");assert.equal(el('page-title').textContent,'A home for every invoice.');assert.equal((el('invoice-rows').innerHTML.match(/<tr>/g)||[]).length,9);run(\"navigate('overview')\");});
check('Friendly reminder opens a prefilled email',()=>{run('reminders()');el('reminder-message').value='A friendly reminder';el('open-email').onclick();assert(context.window.location.href.startsWith('mailto:accounts%40notion.so?'));assert(context.window.location.href.includes('INV-2026-041'));});
check('Client list, reports, and profile settings open',()=>{run('showClients()');assert(el('modal-root').innerHTML.includes('Test &amp; Co'));run('showReports()');assert(el('modal-root').innerHTML.includes('The bigger picture.'));run('settings()');el('profile-form').onsubmit({preventDefault(){},target:{name:'Alex Lane',email:'alex@example.com'}});assert.equal(el('profile-name').textContent,'Alex Lane');});
Promise.all(downloads.map(b=>b.text())).then(([invoice,csv])=>{assert(invoice.includes('Test & Co'));assert(csv.includes('Invoice,Client,Email'));assert(csv.includes('\"Test & Co\"'));console.log('PASS Download contents');console.log('All functional checks passed.');});
EOF
